/*
 * Anotou? — store links, platform detection and the StoreBadges component.
 * THE single place for store URLs (R1).
 *
 * Markup: <div class="store-badges" data-store-badges></div>. The pages ship
 * the "both badges" markup in the initial HTML (generated by
 * scripts/inject-store-badges.mjs, checked by tests), so there is always a link
 * without JS. After DOMContentLoaded this script detects the platform and, on
 * iOS/Android only, swaps in a single badge plus a small text link.
 *
 * Optional attributes: data-base="/" prefixes the badge image paths (pages not
 * at the site root, such as the invite page, which is served at /l/<token>);
 * data-play-referrer="<value>" appends &referrer=<value>
 * (URL-encoded) to the Google Play links (used by the invite page).
 *
 * Works in the browser (window.ANOTOU_STORES) and in Node (module.exports).
 */
(function (root) {
  'use strict';

  var STORES = {
    APP_STORE_ID: '6833691522',
    APP_STORE_URL: {
      pt: 'https://apps.apple.com/br/app/anotou/id6833691522',
      en: 'https://apps.apple.com/us/app/anotou/id6833691522'
    },
    PLAY_STORE_URL: {
      pt: 'https://play.google.com/store/apps/details?id=dev.barrt.anotou&hl=pt_BR',
      en: 'https://play.google.com/store/apps/details?id=dev.barrt.anotou&hl=en_US'
    }
  };

  var LANGS = [['pt', 'pt-BR'], ['en', 'en']];

  var BADGE = {
    appstore: {
      pt: { src: 'badges/app-store-pt-BR.svg', alt: 'Baixar na App Store', w: 120, h: 40 },
      en: { src: 'badges/app-store-en-US.svg', alt: 'Download on the App Store', w: 120, h: 40 }
    },
    play: {
      pt: { src: 'badges/google-play-pt-BR.svg', alt: 'Disponível no Google Play', w: 239, h: 71 },
      en: { src: 'badges/google-play-en-US.svg', alt: 'Get it on Google Play', w: 239, h: 71 }
    }
  };

  var ALSO = {
    appstore: { pt: 'Também na App Store', en: 'Also on the App Store' },
    play: { pt: 'Também no Google Play', en: 'Also on Google Play' }
  };

  /** 'ios' | 'android' | 'desktop' (anything else, including failures). */
  function detectPlatform(userAgent, maxTouchPoints) {
    var ua = String(userAgent || '');
    if (/iPhone|iPad|iPod/i.test(ua)) return 'ios';
    // iPadOS reports itself as a Mac; tell them apart by touch support.
    if (/Macintosh/i.test(ua) && Number(maxTouchPoints) > 1) return 'ios';
    if (/Android/i.test(ua)) return 'android';
    return 'desktop';
  }

  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); }

  function href(store, lang, playReferrer) {
    if (store === 'appstore') return STORES.APP_STORE_URL[lang];
    var u = STORES.PLAY_STORE_URL[lang];
    return playReferrer ? u + '&referrer=' + encodeURIComponent(playReferrer) : u;
  }

  // One <a> per page language; CSS (html[data-lang]) shows the active one, so a
  // PT/EN switch needs no re-render. Badge images are untouched official SVGs.
  function badge(store, opts) {
    return LANGS.map(function (l) {
      var b = BADGE[store][l[0]];
      return '<a class="store-badge store-badge--' + store + '" lang="' + l[1] + '" href="' +
        esc(href(store, l[0], opts.playReferrer)) + '" target="_blank" rel="noopener">' +
        '<img src="' + esc(opts.base || '') + b.src + '" alt="' + esc(b.alt) + '" width="' + b.w + '" height="' + b.h + '"></a>';
    }).join('');
  }

  function alsoLink(store, opts) {
    return LANGS.map(function (l) {
      return '<a class="store-also" lang="' + l[1] + '" href="' + esc(href(store, l[0], opts.playReferrer)) +
        '" target="_blank" rel="noopener">' + ALSO[store][l[0]] + '</a>';
    }).join('');
  }

  /** Inner HTML of the component for a platform. opts: { playReferrer }. */
  function renderBadges(platform, opts) {
    opts = opts || {};
    if (platform === 'ios') {
      return '<div class="store-row">' + badge('appstore', opts) + '</div>' +
        '<p class="store-also-line">' + alsoLink('play', opts) + '</p>';
    }
    if (platform === 'android') {
      return '<div class="store-row">' + badge('play', opts) + '</div>' +
        '<p class="store-also-line">' + alsoLink('appstore', opts) + '</p>';
    }
    return '<div class="store-row">' + badge('appstore', opts) + badge('play', opts) + '</div>';
  }

  /** What a visitor with this userAgent gets (detection + render, as init() does). */
  function renderForUserAgent(userAgent, maxTouchPoints, opts) {
    return renderBadges(detectPlatform(userAgent, maxTouchPoints), opts);
  }

  var api = {
    STORES: STORES,
    detectPlatform: detectPlatform,
    renderBadges: renderBadges,
    renderForUserAgent: renderForUserAgent
  };

  if (typeof module !== 'undefined' && module.exports) { module.exports = api; return; }

  root.ANOTOU_STORES = STORES;
  root.ANOTOU_STORES_API = api;

  // ---- browser only ----
  var doc = root.document;

  // iOS Smart App Banner with app-argument: only on pages that opt in
  // (<html data-smart-banner>, the invite page). The home page has a static
  // <meta name="apple-itunes-app"> in its HTML instead.
  if (doc.documentElement.hasAttribute('data-smart-banner')) {
    var meta = doc.createElement('meta');
    meta.name = 'apple-itunes-app';
    meta.content = 'app-id=' + STORES.APP_STORE_ID + ', app-argument=' + root.location.href;
    doc.head.appendChild(meta);
  }
  function init() {
    var platform = 'desktop';
    var ua = '', touch = 0;
    try { ua = root.navigator.userAgent; touch = root.navigator.maxTouchPoints; platform = detectPlatform(ua, touch); } catch (e) { /* keep desktop */ }
    var nodes = doc.querySelectorAll('[data-store-badges]');
    for (var i = 0; i < nodes.length; i++) {
      var opts = {
        base: nodes[i].getAttribute('data-base') || '',
        playReferrer: nodes[i].getAttribute('data-play-referrer') || ''
      };
      // Desktop/unknown: the initial HTML is already right, so avoid a re-render
      // (no image reload, no shift) unless a Play referrer has to be added.
      if (platform !== 'desktop' || opts.playReferrer) nodes[i].innerHTML = renderBadges(platform, opts);
      nodes[i].setAttribute('data-platform', platform);
    }
  }
  if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', init);
  else init();
})(typeof window !== 'undefined' ? window : this);
